CREATE TABLE IF NOT EXISTS standard_point_configs (id BIGINT AUTO_INCREMENT PRIMARY KEY, config_code VARCHAR(80) NOT NULL, points INT NOT NULL DEFAULT 0, enabled BOOLEAN NOT NULL DEFAULT TRUE, description VARCHAR(255), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, CONSTRAINT uk_standard_point_code UNIQUE(config_code));
CREATE TABLE IF NOT EXISTS monthly_performance_configs (id BIGINT AUTO_INCREMENT PRIMARY KEY, month_key VARCHAR(7) NOT NULL, target_points INT NOT NULL DEFAULT 0, multiplier DOUBLE NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, CONSTRAINT uk_perf_month UNIQUE(month_key));
